import { createBuildingObject } from './buildings/index.js';
import { GltfLoader } from './gltf/index.js';
export function createBuildingsPlugin() {
    return {
        name: 'sekai64-buildings',
        setup(context) {
            const cleanups = ['building', 'text-panel', 'image-panel', 'product-display'].map(type => context.registerObjectType(type, (definition, path) => createBuildingObject(definition, path)));
            return () => { for (const cleanup of cleanups.reverse())
                cleanup(); };
        }
    };
}
export function createGltfPlugin(options = {}) {
    const loader = new GltfLoader();
    return {
        name: 'sekai64-gltf',
        setup(context) {
            const unregister = context.registerObjectType('gltf-model', async (definition, path) => {
                const source = definition.source;
                if (typeof source !== 'string')
                    throw new Error(`${path}.source must be a glTF or GLB URL.`);
                const resolved = options.baseUrl ? new URL(source, options.baseUrl) : source;
                return loader.loadNode(resolved, { id: definition.id, name: definition.name });
            });
            return () => { unregister(); loader.dispose(); };
        }
    };
}
export function createBrowserActionsPlugin(options = {}) {
    const allowed = new Set(options.allowedProtocols ?? ['http:', 'https:', 'mailto:']);
    return {
        name: 'sekai64-browser-actions',
        setup(context) {
            return context.registerSceneAction('open-url', value => {
                if (typeof value !== 'string')
                    throw new Error('open-url requires a string URL.');
                const url = new URL(value, typeof location !== 'undefined' ? location.href : 'https://localhost/');
                if (!allowed.has(url.protocol))
                    throw new Error(`URL protocol is not allowed: ${url.protocol}`);
                if (options.navigate)
                    options.navigate(url);
                else if (typeof window !== 'undefined')
                    window.location.assign(url.href);
                else
                    throw new Error('Browser navigation is unavailable in this environment.');
            });
        }
    };
}
export function bindJsonInteractions(engine, manager, definition) {
    const cleanups = [];
    const visit = (objects) => {
        for (const object of objects) {
            if (object.id && object.interactions) {
                const node = manager.scene.get(object.id);
                if (node) {
                    for (const [eventName, action] of Object.entries(object.interactions)) {
                        if (!isInteractionType(eventName))
                            continue;
                        cleanups.push(manager.onObject(node, eventName, event => { void engine.runSceneAction(action.action, action.value, { objectId: object.id, source: event.originalEvent }); }));
                    }
                }
            }
            if (object.children)
                visit(object.children);
        }
    };
    visit(definition.scene.objects ?? []);
    return () => { for (const cleanup of cleanups.reverse())
        cleanup(); };
}
function isInteractionType(value) {
    return ['pointerenter', 'pointerleave', 'pointermove', 'pointerdown', 'pointerup', 'click', 'doubleclick', 'focus', 'blur'].includes(value);
}